	if subdomain == "" {
		return false
	}

	// Check if the subdomain contains only valid characters and does not start or end with a hyphen
	for i, r := range subdomain {
		if !(r == '-' || r == '.' || unicode.IsLetter(r) || unicode.IsDigit(r)) {
			return false
		}
