			return false
		}
	}

	// Check for consecutive dots
	if strings.Contains(subdomain, "..") {
		return false
	}

	// Check the length of each label in the subdomain
	labels := strings.Split(subdomain, ".")
	for _, label := range labels {
		if len(label) == 0 || len(label) > 63 {
			return false
		}
	}

	return true
}
