char *read_file_from_dir(const char *filename, const char *dir_path) {
    if (filename == NULL || dir_path == NULL) {
        return strdup("");
    }

    // Validate filename and dir_path to prevent path traversal
    if (strstr(filename, "..") != NULL || strstr(dir_path, "..") != NULL) {
        return strdup("");
    }

    // Construct the full path
    size_t dir_len = strlen(dir_path);
    size_t file_len = strlen(filename);
    size_t path_length = dir_len + file_len + 2; // 1 for '/' and 1 for '\0'

    char *full_path = (char *)malloc(path_length);
    if (full_path == NULL) {
        return strdup("");
    }

    // Ensure correct path construction
    if (dir_path[dir_len - 1] == '/') {
        snprintf(full_path, path_length, "%s%s", dir_path, filename);
    } else {
        snprintf(full_path, path_length, "%s/%s", dir_path, filename);
    }

    // Open the file
    FILE *file = fopen(full_path, "r");
    free(full_path);

    if (file == NULL) {
        return strdup("");
    }

    // Determine file size
    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return strdup("");
    }
    long file_size = ftell(file);
    if (file_size < 0) {
        fclose(file);
        return strdup("");
    }
    rewind(file);

    // Allocate memory for file content
    char *content = (char *)malloc(file_size + 1);
    if (content == NULL) {
        fclose(file);
        return strdup("");
    }

    // Read file content
    size_t read_size = fread(content, 1, file_size, file);
    fclose(file);

    if (read_size != file_size) {
        free(content);
        return strdup("");
    }

    content[file_size] = '\0';
    return content;
}
