        if (PKCS5_PBKDF2_HMAC(passwords[i].c_str(), passwords[i].length(), salt.data(), hash_len, iterations, EVP_sha256(), hash_len, hash.data()) != 1) {
            throw std::runtime_error("Error hashing password");
        }

        result.emplace_back(hash, salt);
    }

    return result;
}
